type Option = { value: string; label: string };
type Field = { name: string; label: string; type?: string; options?: Option[]; required?: boolean; placeholder?: string; defaultValue?: string; help?: string };
const DIMENSIONS: Option[] = [
  { value: 'mass', label: '质量' }, { value: 'volume', label: '体积' }, { value: 'amount', label: '物质的量' },
  { value: 'activity', label: '活性' }, { value: 'count', label: '计数' },
];
const CALC_TYPES: Option[] = [
  { value: 'ratio', label: '比例缩放' }, { value: 'mass_concentration', label: '质量浓度' },
  { value: 'molar_concentration', label: '摩尔浓度' }, { value: 'stock_dilution', label: '母液稀释 C₁V₁=C₂V₂' },
  { value: 'volume_fraction', label: '体积分数' }, { value: 'fixed_addition', label: '固定添加量' },
];
const MASS_CONCENTRATION_UNITS = ['µg/mL','mg/mL','mg/L','g/L','g/mL'];
const MOLAR_CONCENTRATION_UNITS = ['µmol/L','mmol/L','mol/L'];
const STOCK_CONCENTRATION_UNITS = [...MASS_CONCENTRATION_UNITS, ...MOLAR_CONCENTRATION_UNITS];
const DIMENSION_LABEL: Record<string,string> = Object.fromEntries(DIMENSIONS.map(x => [x.value,x.label]));
const MOVEMENT_LABEL: Record<string,string> = { RECEIVE:'入库',USE:'使用',TRANSFER_OUT:'移出',TRANSFER_IN:'移入',LOSS:'报损',ADJUST_IN:'盘盈',ADJUST_OUT:'盘亏',PREPARATION_USE:'配液消耗',REVERSAL:'冲销' };
const STATUS_LABEL: Record<string,string> = { active:'可用',quarantined:'隔离',disabled:'停用',expired:'过期',planned:'待执行',completed:'已完成',aborted:'已中止',draft:'草稿',published:'已发布',retired:'已停用' };

async function api(path: string, init: RequestInit = {}) {
  const headers = new Headers(init.headers || {});
  if (init.body && !(init.body instanceof FormData)) headers.set('Content-Type','application/json');
  const response = await fetch(path, { ...init, headers, credentials:'include' });
  const type = response.headers.get('content-type') || '';
  const data = type.includes('json') ? await response.json() : await response.text();
  if (!response.ok) throw new Error(data?.error || `请求失败 (${response.status})`);
  return data;
}
const send = (path: string, body: any, method = 'POST') => api(path,{ method, body: JSON.stringify(body) });
const fmtDate = (value?: string) => value ? new Date(value.replace(' ','T')+'Z').toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}) : '—';
const fmtDay = (value?: string) => value ? value.slice(0,10) : '—';
const num = (value: any) => Number(value || 0).toLocaleString('zh-CN',{maximumFractionDigits:6});

